select json_build_object('columns',(select json_agg(x) from (select * from information_schema.column_privileges where table_schema='public' and table_name='olt_onts' order by column_name,grantee,privilege_type)x),'guard',(select json_build_object('definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'searchPath',p.proconfig) from pg_proc p where p.oid=to_regprocedure('public.guard_olt_ont_retirement()')),'rowCount',(select count(*) from public.olt_onts));